    @Override public void onCreate(Bundle state){
        super.onCreate(state);prefs=getSharedPreferences("arena",MODE_PRIVATE);CrashDiagnostics.install(prefs);api=new ArenaApi(this);ads=new AdsController(this);ads.telemetry((event,micros,currency,precision)->{if(prefs.getBoolean("analyticsConsent",false)&&prefs.getBoolean("connected",false))api.postPlayer(ArenaApi.body("ad-event","id",java.util.UUID.randomUUID().toString(),"event",event,"micros",micros,"currency",currency,"precision",precision),(v,e)->{});});
        section=prefs.getBoolean("onboarded",false)?"home":"welcome";
        if(Build.VERSION.SDK_INT>=33)getOnBackInvokedDispatcher().registerOnBackInvokedCallback(0,this::goBack);
        render();handler.post(ticker);if(prefs.getBoolean("connected",false))refresh();
    }
    private int dp(float n){return Math.round(n*getResources().getDisplayMetrics().density);}
    private GradientDrawable bg(int color,int radius){GradientDrawable d=new GradientDrawable();d.setColor(color);d.setCornerRadius(dp(radius));return d;}
    private TextView text(String value,float size,int color,boolean bold){
        TextView t=new TextView(this);t.setText(value);t.setTextSize(Math.max(12,size));t.setTextColor(color);
        t.setTypeface(ArenaDesign.font(this,bold?"rubik-500":"rubik-400"));t.setLineSpacing(dp(2),1);t.setTextIsSelectable(false);return t;
    }
    private TextView display(String value,float size){TextView t=text(value,size,INK,false);t.setTypeface(ArenaDesign.font(this,"dela"));return t;}
    private void addText(LinearLayout parent,String value,float size,int color,boolean bold,int bottom){TextView t=text(value,size,color,bold);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.bottomMargin=dp(bottom);parent.addView(t,p);}
    private void heading(String value){TextView t=display(value,26);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.topMargin=dp(9);p.bottomMargin=dp(22);content.addView(t,p);}
    private LinearLayout column(){LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.VERTICAL);return l;}
    private LinearLayout row(){LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.HORIZONTAL);l.setGravity(Gravity.CENTER_VERTICAL);return l;}
    private void gap(LinearLayout parent,int n){View v=new View(this);parent.addView(v,new LinearLayout.LayoutParams(1,dp(n)));}
    private void line(LinearLayout parent){View v=new View(this);v.setBackgroundColor(LINE);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,dp(1));p.topMargin=dp(12);p.bottomMargin=dp(12);parent.addView(v,p);}
    private LinearLayout panel(LinearLayout parent,int color,int padding){LinearLayout c=column();c.setPadding(dp(padding),dp(padding),dp(padding),dp(padding));c.setBackground(bg(color,18));c.setClipToOutline(true);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.bottomMargin=dp(18);parent.addView(c,p);return c;}
    private LinearLayout card(int color){return panel(content,color,18);}
    private void clickable(View v,String label,Runnable action){v.setContentDescription(label);v.setFilterTouchesWhenObscured(true);v.setFocusable(true);v.setOnClickListener(x->{if(!busy){if(prefs.getBoolean("haptic",true))v.performHapticFeedback(android.view.HapticFeedbackConstants.KEYBOARD_TAP);action.run();}});}
    private Button button(String label,int color,int fg,Runnable action){Button b=new Button(this);b.setText(label);b.setAllCaps(false);b.setTextSize(14);b.setTextColor(fg);b.setTypeface(ArenaDesign.font(this,"rubik-500"));b.setPadding(dp(12),dp(10),dp(12),dp(10));b.setMinHeight(dp(50));b.setMinimumHeight(dp(50));b.setBackground(bg(color,13));clickable(b,label,action);b.setEnabled(!busy);if(busy)b.setAlpha(.65f);return b;}
    private void addButton(LinearLayout parent,String label,int color,int fg,Runnable action){Button b=button(label,color,fg,action);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.topMargin=dp(10);parent.addView(b,p);}
    private View icon(String name,String label,Runnable action){FrameLayout wrap=new FrameLayout(this);ArenaDesign.Icon i=new ArenaDesign.Icon(this,name,INK);FrameLayout.LayoutParams p=new FrameLayout.LayoutParams(dp(21),dp(21),Gravity.CENTER);wrap.addView(i,p);wrap.setMinimumHeight(dp(44));wrap.setMinimumWidth(dp(44));clickable(wrap,label,action);return wrap;}
    private String title(String game){return ArenaDesign.title(game);}
    private void go(String target){if(section.equals("bank-method")&&!target.equals("bank-method")){bankName="";bankIban="";bankOwn=false;}if(target.equals("support")){section=target;loadServices();return;}if(target.equals("history")&&prefs.getBoolean("connected",false)){section=target;historyPage=0;loadServices();return;}if(target.equals("wallet")){section=target;walletData=null;loadWallet();return;}if(target.equals("live")){section=target;competitionData=null;loadCompetitions();return;}if(target.equals("privacy")||target.equals("terms"))legalReturn=section;section=target;error="";render();}
    private void detail(String game){detailGame=game;go("detail");}
    private String playerName(){return dashboard==null?prefs.getString("name","Oyuncu"):dashboard.optJSONObject("player").optString("name","Oyuncu");}
    private void render(){
        finalCountdown=null;connectionStatus=null;survivorStatus=null;timer=null;timerBar=null;memoryButtons=null;memoryStatus=null;wordInput=null;
        root=column();root.setBackgroundColor(BG);
        root.setOnApplyWindowInsetsListener((v,insets)->{if(Build.VERSION.SDK_INT>=30){var i=insets.getInsets(WindowInsets.Type.systemBars()|WindowInsets.Type.displayCutout());v.setPadding(i.left,i.top,i.right,i.bottom);}else v.setPadding(insets.getSystemWindowInsetLeft(),insets.getSystemWindowInsetTop(),insets.getSystemWindowInsetRight(),insets.getSystemWindowInsetBottom());return insets;});
        LinearLayout top=row();top.setPadding(dp(14),dp(10),dp(14),dp(10));
        if(!section.equals("home")||practice!=null||round!=null)top.addView(icon("back","Önceki ekran",this::goBack),new LinearLayout.LayoutParams(dp(40),dp(44)));
        TextView brand=display("bilgiarena",21);SpannableString brandText=new SpannableString("bilgiarena");brandText.setSpan(new ForegroundColorSpan(ArenaDesign.BRAND),5,10,0);brand.setText(brandText);top.addView(brand,new LinearLayout.LayoutParams(0,-2,1));
        top.addView(icon("bell","Bildirimler",()->{if(practice==null&&round==null)go("notifications");}),new LinearLayout.LayoutParams(dp(44),dp(44)));root.addView(top);
        ScrollView scroll=new ScrollView(this);scroll.setFillViewport(true);scroll.setClipToPadding(false);
        content=column();content.setPadding(dp(20),dp(8),dp(20),dp((practice!=null||round!=null)&&getResources().getConfiguration().screenHeightDp<720?12:24));scroll.addView(content);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));
        if(showingResult)renderResult();else if(isLive()&&round.optString("phase").equals("lobby"))renderLiveLobby();else if(practice!=null||round!=null)renderGame();else{
            if(!error.isEmpty()){LinearLayout e=card(ArenaDesign.RED_WASH);addText(e,error,14,INK,false,2);addButton(e,"Yeniden dene",Color.WHITE,INK,this::refresh);}
            switch(section){
                case "welcome":case "login":case "register":case "forgot":renderAccount();break;
                case "games":renderGames();break;case "detail":renderDetail();break;case "league":renderLeague();break;
                case "support":renderSupport();break;case "bank-method":renderBank();break;case "wallet":renderWallet();break;case "live":renderCompetitions();break;case "final":renderFinal();break;case "profile":renderProfile();break;case "edit-profile":renderEditProfile();break;
                case "account-setup":renderAccountSetup();break;case "delete-account":renderDeleteAccount();break;case "privacy":case "terms":renderLegal();break;case "history":renderHistory();break;
                case "notifications":renderNotifications();break;case "settings":renderSettings();addButton(content,"Reklam gizlilik tercihleri",Color.WHITE,INK,()->ads.privacyOptions());break;case "rules":renderRules();break;
                default:renderHome();
            }
            if(!List.of("welcome","login","register","forgot").contains(section))renderNav();
        }
        setContentView(root);root.requestApplyInsets();if(paused)coverScreen();
    }
    private void renderNav(){
        LinearLayout nav=row();nav.setPadding(dp(5),dp(7),dp(5),dp(7));nav.setBackgroundColor(BG);
        String[][] items={{"home","Keşfet"},{"games","Oyunlar"},{"league","Sıralama"},{"history","Geçmiş"},{"profile","Profil"}};
        for(String[] item:items){boolean active=section.equals(item[0]);String iconName=item[0].equals("league")?"ranking":item[0];LinearLayout cell=column();cell.setGravity(Gravity.CENTER);cell.setMinimumHeight(dp(58));cell.addView(new ArenaDesign.Icon(this,iconName,active?INK:MUTED),new LinearLayout.LayoutParams(dp(20),dp(20)));TextView label=text(item[1],12,active?INK:MUTED,active);label.setGravity(Gravity.CENTER);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.topMargin=dp(5);cell.addView(label,p);View mark=new View(this);mark.setBackground(bg(active?ArenaDesign.BRAND:Color.TRANSPARENT,2));LinearLayout.LayoutParams m=new LinearLayout.LayoutParams(dp(16),dp(3));m.topMargin=dp(6);cell.addView(mark,m);clickable(cell,item[1],()->go(item[0]));nav.addView(cell,new LinearLayout.LayoutParams(0,-2,1));}
        root.addView(nav);
    }
    private void renderAccount(){
        if(section.equals("welcome")){
            LinearLayout poster=card(ArenaDesign.poster("reverse"));TextView h=display("Merakına\nbir oyun aç.",35);poster.addView(h);poster.addView(ArenaDesign.art(this,"reverse"),new LinearLayout.LayoutParams(-1,dp(195)));
            addButton(content,"Oyunları keşfet  →",INK,Color.WHITE,()->{prefs.edit().putBoolean("onboarded",true).apply();go("home");});
            addButton(content,"Hesabına giriş yap",Color.TRANSPARENT,INK,()->go("login"));return;
        }
        heading(section.equals("register")?"Oyuncu kartın.":section.equals("forgot")?"Hesabına dön.":"Giriş yap.");
        if(section.equals("register")){
            addText(content,"Oyuncu adın",13,INK,true,8);EditText name=input(prefs.getString("name",""),"2–24 karakter",false);name.setFilters(new android.text.InputFilter[]{new android.text.InputFilter.LengthFilter(24)});content.addView(name);
            addButton(content,"Hesabını oluştur ve bağla  →",INK,Color.WHITE,()->{String n=name.getText().toString().trim();if(!validName(n))return;prefs.edit().putString("pendingName",n).putString("name",n).putBoolean("onboarded",true).apply();signIn();});
        }else addButton(content,"Hesabını bağla  →",INK,Color.WHITE,this::signIn);
        gap(content,18);addText(content,"BilgiArena hesabınla güvenli giriş yap. Giriş ve şifre işlemleri hesap sağlayıcısının ekranında tamamlanır.",14,MUTED,false,10);
        if(!section.equals("register"))addButton(content,"İlk kez mi geliyorsun? Kayıt ol",Color.TRANSPARENT,INK,()->go("register"));
        if(!section.equals("forgot"))addButton(content,"Şifremi unuttum",Color.TRANSPARENT,MUTED,()->go("forgot"));
        addButton(content,"Hesapsız antrenman yap",Color.TRANSPARENT,INK,()->{prefs.edit().putBoolean("onboarded",true).apply();go("games");});
    }
    private void renderHome(){
        LinearLayout titleRow=row();TextView h=display("Oyun zamanı.",27);titleRow.addView(h,new LinearLayout.LayoutParams(0,-2,1));View av=ArenaDesign.art(this,"avatar");av.setBackground(bg(0xff6a9d80,30));av.setClipToOutline(true);clickable(av,"Oyuncu profili",()->go("profile"));titleRow.addView(av,new LinearLayout.LayoutParams(dp(40),dp(40)));content.addView(titleRow);gap(content,18);
        line(content);LinearLayout league=row();league.addView(text(dashboard==null||dashboard.isNull("rank")?"—":dashboard.optInt("rank")+".",23,INK,true));TextView label=text("  Haftalık sıra",12,MUTED,false);league.addView(label,new LinearLayout.LayoutParams(0,-2,1));league.addView(text((dashboard==null?0:dashboard.optInt("weeklyScore"))+" puan  ›",16,INK,true));clickable(league,"Haftalık sıralamayı gör",()->go("league"));content.addView(league);line(content);
        if(dashboard!=null&&dashboard.optJSONObject("pending")!=null)addButton(content,"Yarım kalan tura dön",INK,Color.WHITE,()->resumeRound(dashboard.optJSONObject("pending").optString("id")));
        if(dashboard!=null){JSONObject progress=dashboard.optJSONObject("progress");if(progress!=null){LinearLayout goal=card(Color.WHITE);addText(goal,"Günlük hedef "+progress.optInt("todayCompleted")+" / 3 tur",18,INK,true,8);addText(goal,progress.optInt("streak")+" günlük seri · En iyi tur "+progress.optInt("personalBest"),13,MUTED,false,8);JSONObject next=progress.optJSONObject("nextCompetition");if(next!=null){finalTarget=next.optLong("startsAt");finalCountdown=text("",18,INK,true);goal.addView(finalCountdown);lastFinalSecond=-1;}if(next!=null)addButton(goal,next.optString("title")+" · "+when(next.optLong("startsAt")),INK,Color.WHITE,()->go("live"));}}
        LinearLayout hero=card(ArenaDesign.poster("reverse"));TextView stamp=text("10–15 sn",12,INK,true);hero.addView(stamp);hero.addView(ArenaDesign.art(this,"reverse"),new LinearLayout.LayoutParams(-1,dp(130)));LinearLayout r=row();r.addView(display("Ters Köşe",24),new LinearLayout.LayoutParams(0,-2,1));r.addView(button("Oyna  →",INK,Color.WHITE,()->detail("reverse")));hero.addView(r);
        LinearLayout sub=row();sub.addView(text("Bir de bunları dene",18,INK,true),new LinearLayout.LayoutParams(0,-2,1));sub.addView(button("Tümü  →",Color.TRANSPARENT,INK,()->go("games")));content.addView(sub);gamePair(content,"memory","math");
        LinearLayout f=panel(content,Color.WHITE,12);LinearLayout fr=row();fr.addView(ArenaDesign.art(this,"prize"),new LinearLayout.LayoutParams(dp(55),dp(60)));LinearLayout labels=column();addText(labels,"HAFTALIK FİNAL",12,MUTED,false,4);addText(labels,"Final ve provalar",18,INK,true,0);fr.addView(labels,new LinearLayout.LayoutParams(0,-2,1));fr.addView(new ArenaDesign.Icon(this,"arrow",INK),new LinearLayout.LayoutParams(dp(20),dp(20)));f.addView(fr);clickable(f,"Eleme provası",()->go("final"));
        if(dashboard==null)addButton(content,"Lig için hesabını bağla",Color.TRANSPARENT,INK,()->go("login"));
    }
    private void gamePair(LinearLayout parent,String a,String b){LinearLayout r=row();r.setGravity(Gravity.TOP);for(String game:new String[]{a,b}){LinearLayout tile=column();View art=ArenaDesign.art(this,game);art.setBackground(bg(ArenaDesign.poster(game),16));art.setClipToOutline(true);tile.addView(art,new LinearLayout.LayoutParams(-1,dp(130)));TextView label=text(title(game)+"  ↗",14,INK,true);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.topMargin=dp(9);tile.addView(label,lp);LinearLayout.LayoutParams tp=new LinearLayout.LayoutParams(0,-2,1);if(game.equals(a))tp.rightMargin=dp(6);else tp.leftMargin=dp(6);r.addView(tile,tp);clickable(tile,title(game),()->detail(game));}parent.addView(r);gap(parent,22);}
    private void renderGames(){heading("Oyun salonu.");for(int i=0;i<GAMES.length;i+=2)gamePair(content,GAMES[i],GAMES[i+1]);}
    private void renderDetail(){
        View art=ArenaDesign.art(this,detailGame);art.setBackground(bg(ArenaDesign.poster(detailGame),20));art.setClipToOutline(true);content.addView(art,new LinearLayout.LayoutParams(-1,dp(205)));heading(title(detailGame));
        String desc=switch(detailGame){case "word"->"Karışan harfleri doğru sıraya koy.";case "memory"->"Işık dizisini izle. Aynı sırayla dokun.";case "math"->"Denklemdeki eksik sayıyı bul.";case "colors"->"Kelimeyi değil, yazının rengini seç.";case "trivia"->"Doğru platformu seç. Seçimin süre kapanana kadar gizli.";default->"Tersten yazılan kelimeyi doğru yönde yaz.";};
        addText(content,desc,16,INK,false,20);addText(content,"10 aşama · 10/15 sn · doğru başına 10 puan",13,MUTED,false,15);
        if(dashboard!=null&&dashboard.optInt("rankedRemaining")>0)addButton(content,"Karma puanlı tur  ·  "+dashboard.optInt("rankedRemaining")+" / 3",INK,Color.WHITE,()->startOnline(detailGame,"ranked"));
        else if(dashboard!=null)addText(content,"Bugünkü 3 puanlı turun tamamlandı. Antrenmanlar açık.",14,MUTED,true,12);
        else addButton(content,"Puanlı oynamak için giriş yap",INK,Color.WHITE,()->go("login"));
        addButton(content,"Antrenman yap  →",Color.WHITE,INK,()->startPractice(detailGame));
        addText(content,"Antrenman sınırsızdır. Haftalık puana eklenmez.",12,MUTED,false,0);
    }
    private void renderLeague(){if(dashboard!=null&&dashboard.optJSONObject("progress")!=null){JSONObject p=dashboard.optJSONObject("progress");addText(content,p.optBoolean("isCashEligible")?(p.isNull("cashRank")?"Nakit final sırası henüz yok.":"Nakit final sıran: "+p.optInt("cashRank")):"Yönetici hesabı nakit final listesine katılmaz.",14,INK,true,8);if(!p.isNull("cashCutoffScore"))addText(content,"200. sıra: "+p.optInt("cashCutoffScore")+" puan · Öne geçmek için "+p.optInt("pointsToFinal")+" puan",13,MUTED,false,12);}
        heading("Haftalık sıralama.");addText(content,"Haftanın ilk 200 oyuncusu.",14,MUTED,false,20);
        JSONArray leaders=dashboard==null?null:dashboard.optJSONArray("leaders");
        if(leaders==null||leaders.length()==0){addText(content,dashboard==null?"Sıralamanı görmek için hesabını bağla.":"Bu haftanın ilk puanını sen topla.",17,INK,true,18);if(dashboard==null)addButton(content,"Giriş yap",INK,Color.WHITE,()->go("login"));else addButton(content,"Oyunlara git",INK,Color.WHITE,()->go("games"));return;}
        LinearLayout podium=row();for(int i=0;i<Math.min(3,leaders.length());i++){JSONObject p=leaders.optJSONObject(i);LinearLayout cell=column();cell.setGravity(Gravity.CENTER);cell.addView(avatar(p.optString("name"),p.optString("avatar","mint")),new LinearLayout.LayoutParams(dp(52),dp(52)));TextView name=text(p.optString("name"),13,INK,true);name.setGravity(Gravity.CENTER);cell.addView(name);TextView rank=display(""+(i+1),26);rank.setGravity(Gravity.CENTER);rank.setPadding(0,dp(12+i*2),0,dp(8));rank.setBackground(bg(i==0?ArenaDesign.poster("reverse"):LINE,10));cell.addView(rank,new LinearLayout.LayoutParams(-1,-2));TextView points=text(p.optInt("score")+" puan",12,MUTED,false);points.setGravity(Gravity.CENTER);cell.addView(points);LinearLayout.LayoutParams cp=new LinearLayout.LayoutParams(0,-2,1);cp.setMargins(dp(4),0,dp(4),dp(22));podium.addView(cell,cp);}content.addView(podium);
        for(int i=3;i<leaders.length();i++){JSONObject p=leaders.optJSONObject(i);LinearLayout r=row();r.setPadding(dp(8),dp(14),dp(8),dp(14));if(p.optBoolean("isMe"))r.setBackground(bg(ArenaDesign.GREEN_WASH,10));r.addView(text(p.optInt("rank")+".",14,MUTED,false),new LinearLayout.LayoutParams(dp(32),-2));r.addView(text(p.optString("name")+(p.optBoolean("isMe")?" · Sen":""),14,INK,true),new LinearLayout.LayoutParams(0,-2,1));r.addView(text(""+p.optInt("score"),16,INK,true));content.addView(r);}
        addButton(content,"Sıralamayı yenile",Color.TRANSPARENT,INK,this::refresh);
    }
    private void renderFinal(){
        heading("Haftalık final.");addButton(content,"Canlı yarışmalar  →",INK,Color.WHITE,()->{if(dashboard==null)go("login");else go("live");});LinearLayout poster=card(0xff303234);addText(poster,"10 aşama. Tek hedef.",16,0xfffffdf1,true,8);TextView prize=display("Eleme",36);prize.setTextColor(0xfffffdf1);poster.addView(prize);poster.addView(ArenaDesign.art(this,"prize"),new LinearLayout.LayoutParams(-1,dp(180)));addText(poster,"Bilgisayar rakipleriyle antrenman",13,0xfffffdf1,false,0);
        addText(content,"Ücretsiz oyun · Puanların parasal karşılığı yoktur.",13,MUTED,true,14);addText(content,"Final provasındaki 199 rakip simülasyondur. Yanlış cevap veya süre aşımı eler. Seçimler ortak süre dolunca açılır.",14,INK,false,16);
        addButton(content,"Final provasını oyna  →",INK,Color.WHITE,()->{if(dashboard==null)go("login");else startOnline("trivia","final");});
        addButton(content,"Haftalık sıralamam",Color.TRANSPARENT,INK,()->go("league"));
    }
    private void stat(LinearLayout parent,String value,String label){LinearLayout col=column();col.setGravity(Gravity.CENTER);TextView n=text(value,22,INK,true);n.setGravity(Gravity.CENTER);col.addView(n);TextView l=text(label,12,MUTED,false);l.setGravity(Gravity.CENTER);col.addView(l);parent.addView(col,new LinearLayout.LayoutParams(0,-2,1));}
