                String l=letters();for(int offset=0;offset<l.length();offset+=5){LinearLayout keys=row();keys.setGravity(Gravity.CENTER);for(int i=offset;i<Math.min(l.length(),offset+5);i++){final int at=i;Button keyButton=button(l.substring(i,i+1),0xfffffdf1,INK,()->{letterPicks.add(at);StringBuilder v=new StringBuilder();for(int p:letterPicks)v.append(letters().charAt(p));draft=v.toString();render();});keyButton.setTextSize(22);keyButton.setPadding(0,0,0,0);keyButton.setEnabled(enabled&&!letterPicks.contains(i));if(letterPicks.contains(i))keyButton.setAlpha(.3f);LinearLayout.LayoutParams kp=new LinearLayout.LayoutParams(dp(43),dp(49));kp.setMargins(dp(3),dp(8),dp(3),0);keys.addView(keyButton,kp);}content.addView(keys);}
