 private java.util.Set<String> recentPractice(){return new java.util.HashSet<>(prefs.getStringSet("recentPractice",java.util.Set.of()));}
 private void rememberPractice(){if(practice==null)return;var recent=new java.util.ArrayList<String>(java.util.Arrays.asList(prefs.getString("recentPracticeOrder","").split("\\n")));recent.remove("");for(String key:practice.fingerprints()){recent.remove(key);recent.add(key);}while(recent.size()>40)recent.remove(0);prefs.edit().putString("recentPracticeOrder",String.join("\n",recent)).putStringSet("recentPractice",new java.util.HashSet<>(recent)).apply();}
 private boolean crashReportInFlight;
