    private void tick(){
        if(finalCountdown!=null){long seconds=Math.max(0,(finalTarget-System.currentTimeMillis())/1000);if(seconds!=lastFinalSecond){lastFinalSecond=seconds;finalCountdown.setText(seconds==0?"Katılım odasını kontrol et":String.format(new Locale("tr","TR"),"Finale %02d:%02d:%02d",seconds/3600,(seconds/60)%60,seconds%60));}}
        if(!paused&&isLive()&&!showingResult&&!livePolling&&!busy&&SystemClock.elapsedRealtime()>=nextLivePoll){nextLivePoll=SystemClock.elapsedRealtime()+2000;pollLive();}
        if(timer==null||paused)return;
        if(practice!=null&&!practice.waiting())return;
        if(round!=null&&round.optJSONObject("feedback")!=null)return;
        if(practice==null&&(round==null||(round.optJSONObject("question")==null&&!round.optBoolean("locked"))))return;
        long remaining=practice!=null?practice.remaining(SystemClock.elapsedRealtime()):Math.max(0,(round.optJSONObject("question")!=null?round.optJSONObject("question").optLong("deadline"):round.optLong("revealAt"))-round.optLong("serverNow")-(SystemClock.elapsedRealtime()-receivedAt));
        timer.setText((long)Math.ceil(remaining/1000.0)+" sn");timer.setTextColor(remaining<=3000?ArenaDesign.RED:INK);timerBar.setProgressTintList(ColorStateList.valueOf(remaining<=3000?ArenaDesign.RED:INK));timerBar.setProgress((int)remaining);
        if(practice!=null||!locked())paintMemory();
        if(remaining==0&&!busy&&!isLive()&&error.isEmpty()){if(locked()){long now=SystemClock.elapsedRealtime();if(now>=nextResumeAt){nextResumeAt=now+1000;resumeRound(round.optString("id"));}}else sendAnswer(null);}
    }
