    private void goBack(){
        if(busy)return;
        if(section.equals("privacy")||section.equals("terms")){go(legalReturn);return;}
        if(historyResult!=null){historyResult=null;showingResult=false;go("history");return;}
        if(showingResult){practice=null;round=null;shownQuestion=null;showingResult=false;go("games");return;}
        if(isLive()){secureDialog(new AlertDialog.Builder(this).setTitle("Canlı finalden çıkılsın mı?").setMessage("Soru sırasında ayrılmak aşamayı kesintiyle kapatır. Ortak süre devam eder.").setNegativeButton("Kal",null).setPositiveButton("Çık",(d,w)->{interrupt("background");round=null;shownQuestion=null;showingResult=false;section="final";render();}));return;}
        if(practice!=null||round!=null){secureDialog(new AlertDialog.Builder(this).setTitle("Turdan ayrılsın mı?").setMessage("Tamamlanmayan turun puanı lige eklenmez. Başlatılmış puanlı tur hakkı geri verilmez.").setNegativeButton("Oyuna dön",null).setPositiveButton("Turdan ayrıl",(d,w)->{
            if(round!=null&&round.optString("status").equals("active")){busy=true;api.post(ArenaApi.body("abandon","roundId",round.optString("id")),(data,e)->{busy=false;if(e!=null){handleError(e);return;}round=null;shownQuestion=null;showingResult=false;historyResult=null;render();refresh();});}
            else{practice=null;round=null;shownQuestion=null;showingResult=false;historyResult=null;render();}
        }));}else if(!section.equals("home")){section="home";render();}else finish();
    }
    // API 33+ is registered with the platform OnBackInvokedDispatcher in onCreate.
    // This override intentionally handles Android 8–12 only.
    @android.annotation.SuppressLint("GestureBackNavigation")
    @Override public void onBackPressed(){goBack();}
    private void interrupt(String reason) {
        if(practice!=null){if(practice.waiting())practice.interrupt(SystemClock.elapsedRealtime());return;}
        if(round==null||!questionActive())return;
        String id=round.optString("id");int index=round.optJSONObject("question").optInt("index");
        // Metadata only; survive process death and retry before displaying that question again.
        prefs.edit().putString("interruptedRound",id).putInt("interruptedIndex",index).putBoolean("interruptedLive",isLive()).commit();
        postRound(ArenaApi.body("interrupt","roundId",id,"index",index,"reason",reason),(data,e)->{
            if(e==null){prefs.edit().remove("interruptedRound").remove("interruptedIndex").apply();if(round!=null&&round.optString("id").equals(id))accept(data);}
            else{error="Kesilen soru kapatılamadı. Bağlantını yenilediğinde yeniden denenecek.";if(!paused)render();}
        });
    }
    @Override protected void onPause(){
        paused=true;if(!isChangingConfigurations())interrupt("background");super.onPause();
    }
    @Override protected void onResume(){
        super.onResume();paused=false;if(afterAd!=null){Runnable next=afterAd;afterAd=null;next.run();}
        if(prefs==null)return;
        String pending=prefs.getString("interruptedRound",null);
        if(pending!=null)retryInterrupted();
        else if(practice!=null)render();
    }
    private void retryInterrupted(){
        String pending=prefs.getString("interruptedRound",null);if(pending==null)return;
        busy=true;coverScreen();postInterrupted(ArenaApi.body("interrupt","roundId",pending,"index",prefs.getInt("interruptedIndex",0),"reason","background"),(data,e)->{
            busy=false;
            if(e==null){prefs.edit().remove("interruptedRound").remove("interruptedIndex").apply();currentGame=data.optString("game","trivia");accept(data);uncoverScreen();return;}
            practice=null;round=null;shownQuestion=null;
            if(e instanceof ArenaApi.ApiException){
                int status=((ArenaApi.ApiException)e).status;
                if(status==404||status==409||status==410||status==428){prefs.edit().remove("interruptedRound").remove("interruptedIndex").apply();error="Önceki tur sona erdi. Yeni bir tur başlatabilirsin.";render();refresh();return;}
                if(status==401){dashboard=null;prefs.edit().putBoolean("connected",false).apply();error="Kesilen turu doğrulamak için hesabını yeniden bağla.";render();return;}
            }
            error="Kesilen tur doğrulanamadı. Çevrimiçi tura devam etmek için bağlantını yenile.";render();
        });
    }
    @Override public void onWindowFocusChanged(boolean focused){super.onWindowFocusChanged(focused);if(!focused&&questionActive())coverScreen();else if(focused&&!paused)uncoverScreen();}
    @Override public void onMultiWindowModeChanged(boolean enabled,Configuration config){super.onMultiWindowModeChanged(enabled,config);if(enabled&&questionActive()){interrupt("multi_window");message("Sorular için uygulamayı tam ekran aç.");}}
    @Override protected void onObscuredInput(){message("Ekranın üstündeki pencereyi kapatıp yeniden dene.");}
    @Override public void onRequestPermissionsResult(int request,String[] permissions,int[] results){super.onRequestPermissionsResult(request,permissions,results);if(request==303&&results.length>0&&results[0]==android.content.pm.PackageManager.PERMISSION_GRANTED){ReminderReceiver.daily(this,true);render();}}
    @Override protected void onDestroy(){handler.removeCallbacksAndMessages(null);if(api!=null)api.close();if(ads!=null)ads.close();super.onDestroy();}

    private boolean isLive(){return round!=null&&round.optBoolean("liveCompetition");}
    private void postRound(JSONObject body,ArenaApi.Callback cb){if(isLive()){try{body.put("action","contest-"+body.optString("action"));}catch(Exception e){throw new IllegalArgumentException(e);}api.postCompetition(body,cb);}else api.post(body,cb);}
    private void postInterrupted(JSONObject body,ArenaApi.Callback cb){if(prefs.getBoolean("interruptedLive",false)){try{body.put("action","contest-interrupt");}catch(Exception e){throw new IllegalArgumentException(e);}api.postCompetition(body,cb);}else api.post(body,cb);}
