    private void renderBank(){heading("Banka hesabın.");if(walletData==null){addButton(content,"Cüzdana dön",INK,Color.WHITE,()->go("wallet"));return;}addText(content,"Yalnızca kendi adına açılmış TR IBAN kullan. IBAN kontrol hanesi hesap sahipliğini veya banka doğrulamasını kanıtlamaz.",14,MUTED,false,16);EditText name=input(bankName,"Hesap sahibinin adı soyadı",false),iban=input(bankIban,"TR IBAN",false);name.setAutofillHints((String[])null);iban.setAutofillHints((String[])null);name.setImportantForAutofill(View.IMPORTANT_FOR_AUTOFILL_NO);iban.setImportantForAutofill(View.IMPORTANT_FOR_AUTOFILL_NO);name.setInputType(android.text.InputType.TYPE_CLASS_TEXT|android.text.InputType.TYPE_TEXT_VARIATION_PERSON_NAME);iban.setFilters(new android.text.InputFilter[]{new android.text.InputFilter.LengthFilter(34)});content.addView(name);content.addView(iban);android.widget.CheckBox own=new android.widget.CheckBox(this);own.setChecked(bankOwn);own.setText("Bu hesap kendi adıma kayıtlıdır.");own.setTextColor(INK);content.addView(own);addButton(content,"Banka kaydını şifreli kaydet",INK,Color.WHITE,()->{if(!own.isChecked()){message("Hesap sahipliğini onayla.");return;}JSONObject m=walletData.optJSONObject("method");bankName=name.getText().toString();bankIban=iban.getText().toString();bankOwn=own.isChecked();walletPost(ArenaApi.body("method-save","recipientName",bankName,"iban",bankIban,"revision",m==null?0:m.optInt("revision"),"ownAccountConfirmed",true));});}
